#!/bin/bash
# batch A1: generated by scripts/make_batch.py from tracks/kb/claims_tracks/decisions/A1.tsv; do not edit by hand
cd /data/haiyangw/nrpic/wt/kb || exit 2
fail=0
test -n "${NRPIC_RUN_DIR:-}" || { echo 'not inside nrpic-run'; exit 2; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py snapshot tracks/kb/claims_tracks/decisions/A1.tsv > "$NRPIC_RUN_DIR/before.json" || fail=1
/usr/bin/python3 -I kb/bin/kb claim verify 34 --by kb-claims_tracks --evidence 'Full-text search of 2609.14218v1 MDPBH.tex: apparent horizons are monitored (L777) but no horizon or black-hole mass is reported; spin only as outlook (L1211-1216); gravitational waves only in introduction and outlook (L215-218, L1218); no accretion; one resolution of 80 cells per direction (L776, L942; 40 in the LTB appendix, L1492), no convergence study; only p=0 runs (L941, L952, L965); no velocity dispersion in the initial data (regular lattice, L1065-1069); no binaries. Read at L941.' || { echo FAILED 34; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 54 --by kb-claims_tracks --evidence '2610.23218v1 main.tex: dust fluid, no particles (L51); perturbation a sum of three cosines (eq. Rc, L71-76), amplitudes not quoted one by one but the face/edge/vertex comparison (L358-360) presupposes cubic symmetry; no apparent horizon: only the hoop ratio 2M/R and a '"'"'black hole radius'"'"' in quotes (L352-360); no mass, spin or threshold (threshold hits: L47 background, L451 a lapse parameter). Locator moved from L51 (approach paragraph) to the perturbation and the hoop paragraphs.' --locator '2610.23218v1:main.tex:L71-76; 2610.23218v1:main.tex:L352-360' || { echo FAILED 54; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 68 --by kb-claims_tracks --evidence 'Full-text search of 1609.01588v2: no simulation of its own (numerical relativity results of others quoted, L307-318; L695 is a numerical integration of beta_0); no spin or angular momentum (no hit); velocity dispersion only as the state after the caustic (L624, L893); inhomogeneity only noted (caption L745-747; L951-978, neglected); fate of the virialised pancakes left open (L619-631).' || { echo FAILED 68; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 89 --by kb-claims_tracks --evidence '2211.13950v3: no simulation (the only hit for simulat is a cited title, L1671); angular momentum and anisotropy enter only the abundance estimate of the section on formation probability (L613-640); O(1) coefficients dropped (L375, L399).' || { echo FAILED 89; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 113 --by kb-claims_tracks --evidence '2508.10070v1 L689: spins computed to first order in the displacement only, nonlinear terms left open; no simulation in the paper (no hit for simulat).' || { echo FAILED 113; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 114 --by kb-claims_tracks --evidence '2508.10070v1 L691-692: accretion not included (listed as open). Terse fragment of the list of claim 113.' || { echo FAILED 114; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 131 --by kb-claims_tracks --evidence '2306.11810v2: scalar fields only (L114, L126; no dust or particles); angular momentum injected through the initial shell (L149), so no run starts non-rotating; L279: evolution followed only a few e-folds after formation.' || { echo FAILED 131; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 168 --by kb-claims_tracks --evidence '1609.01588v2 L619-631: after the caustic the pancakes virialise with large velocity dispersion and may only later collapse by radiating energy; black-hole formation after the caustic is not decided.' || { echo FAILED 168; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 169 --by kb-claims_tracks --evidence 'The line number belongs to 2507.18312 (in 1609.01588 L240 is a TeX comment): 2507.18312v3 Main.tex L240 asks whether a black hole can form after t_c and says its simulations (section SimShell) do not support it; inner shells pass the origin and cross the outer ones.' --locator 2507.18312v3:Main.tex:L240 || { echo FAILED 169; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 7 --by kb-claims_tracks --evidence '2609.14218v1 L476-487: octant 0<=X^i<=L, scale-up non-Cartesian coordinates, eta=10 (L487); central interval enlarged by 1+eta (L485), so 11 is 1+eta (the number the machine did not find).' || { echo FAILED 7; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 28 --by kb-claims_tracks --evidence 'Figure alpha.pdf of the stored source read (caption L1091-1096: e=0.2, N=80): time axis to 250 t_H; the drop of alpha_0 comes later for smaller mu (about 25, 47, 75, 107, 148, 215 t_H for mu=0.3 to 0.05), none for 0.045; halo supported by velocity dispersion L1122-1124, L1138.' --locator '2609.14218v1:MDPBH.tex:L1091-1096; 2609.14218v1:MDPBH.tex:L1122-1124; 2609.14218v1:MDPBH.tex:L1138' || { echo FAILED 28; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 74 --by kb-claims_tracks --evidence '1707.03595v4 L953-962: delta_th is the maximum of three; delta_th(1) = 3*2^2/5^3 q^2 = 12 q^2/125; delta_th(2) = ((2/5) I sigma_H)^(2/3).' || { echo FAILED 74; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 166 --by kb-claims_tracks --evidence 'Hoop criterion with Zel'"'"'dovich deformation: 1609.01588 L596-613, 2508.10070 L339-353, as applied by 2609.14218 (eq. ana_cri, L905-916; abstract L177: particle threshold an order of magnitude below it). The value mu > 0.45 at e=0.2 is the track'"'"'s evaluation (run A-emd-pbh-20261115-112625-e854f12, T1), not printed in the paper. 2507.18312 L242: threshold delta_m ~ 1 for a typical peak. 2609.14218 L1101-1103: horizons with particles for mu >= 0.05 at e=0.2.' --locator '1609.01588v2:apj_nonsphericalpbh.tex:L596-613; 2508.10070v1:main.tex:L339-353; 2609.14218v1:MDPBH.tex:L905-916; 2609.14218v1:MDPBH.tex:L177; 2507.18312v3:Main.tex:L242; 2609.14218v1:MDPBH.tex:L1101-1103' || { echo FAILED 166; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 167 --by kb-claims_tracks --evidence 'Near-extremal rapid rotation (1707.03595 L83, L820); spin ~ sigma^(1/2) (2508.10070 L82, claim 110); a_rms ~ zeta_rms^(7/4) (2507.18312 L635, claim 98); spin falls as non-rotating matter is accreted (2306.11810 L96, L267). '"'"'Nobody has computed it for collisionless matter'"'"' holds within these papers (scalar fields in 2306.11810 L114, analytic estimates in the others; claims 34, 113, 131) [JUDGEMENT beyond the corpus].' --locator '1707.03595v4:Spin_PBH.tex:L83; 2508.10070v1:main.tex:L82; 2507.18312v3:Main.tex:L635; 2306.11810v2:Spinning_PBHs.tex:L96; 2306.11810v2:Spinning_PBHs.tex:L267' || { echo FAILED 167; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/annotate.py annotate tracks/kb/claims_tracks/decisions/A1_annot.tsv || { echo FAILED annotate; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim check --id 34 68 89 113 114 131 168 7 74 --by kb-claims_tracks || { echo FAILED check; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py rows tracks/kb/claims_tracks/decisions/A1.tsv "$NRPIC_RUN_DIR/before.json" "$NRPIC_RUN_ID" > "$NRPIC_RUN_DIR/ledger_rows.tsv" || fail=1
exit $fail
